<script setup>
import {ref,computed,onMounted} from 'vue';
import ReportsView from './views/ReportsView.vue';
import DashboardView from './views/DashboardView.vue';
import DataTable from './components/DataTable.vue';
import StatCard from './components/StatCard.vue';
import {api as httpApi} from './services/api.js';
import {LayoutDashboard,CarFront,UsersRound,Route,ClipboardList,WalletCards,ReceiptText,ShieldCheck,LogOut,Plus,RefreshCw,Search,Trash2,Edit3,X,CheckCircle2,AlertCircle,Menu,FileClock,LockKeyhole,BarChart3,Download} from 'lucide-vue-next';
const token=ref(sessionStorage.getItem('vantai_token')||'');const user=ref(null),loginName=ref('admin'),password=ref(''),loading=ref(false),error=ref(''),notice=ref('');const page=ref('dashboard'),items=ref([]),dashboard=ref({}),refs=ref({drivers:[],vehicles:[],routes:[],periods:[]});const search=ref(''),statusFilter=ref(''),typeFilter=ref(''),dateFrom=ref(''),dateTo=ref(''),modal=ref(false),form=ref({}),editing=ref(false),sidebar=ref(false);
const NAV=[['dashboard','Tổng quan',LayoutDashboard],['vehicles','Quản lý phương tiện',CarFront],['drivers','Hồ sơ tài xế',UsersRound],['routes','Tuyến đường',Route],['bookings','Điều phối chuyến',ClipboardList],['settlements','Đối soát',ReceiptText],['ledger','Công nợ',WalletCards],['reports','Báo cáo',BarChart3],['periods','Kỳ kế toán',FileClock],['users','Tài khoản & phân quyền',ShieldCheck],['audit','Nhật ký thao tác',LockKeyhole]];
const F={vehicles:[['plate','Biển số','text',true],['type','Loại xe','select',true,[['car','Ô tô'],['motorbike','Xe máy']]],['brand','Hãng xe'],['model','Dòng xe'],['manufacture_year','Năm sản xuất','number'],['seats','Số ghế','number'],['driver_id','Tài xế phụ trách','drivers'],['registration_expiry','Hạn đăng kiểm','date'],['insurance_expiry','Hạn bảo hiểm','date'],['owner_name','Chủ xe'],['notes','Ghi chú'],['status','Trạng thái','select',false,[['available','Sẵn sàng'],['maintenance','Bảo trì'],['inactive','Ngừng hoạt động']]]],drivers:[['full_name','Họ và tên','text',true],['phone','Số điện thoại','text',true],['cccd','Số CCCD'],['license_no','Bằng lái'],['license_expiry','Hết hạn GPLX','date'],['address','Địa chỉ'],['status','Trạng thái','select',false,[['active','Đang hoạt động'],['inactive','Ngừng']]]],routes:[['name','Tên tuyến','text',true],['pickup','Điểm đi','text',true],['dropoff','Điểm đến','text',true],['estimated_fare','Giá dự kiến','number']],bookings:[['customer_name','Tên khách','text',true],['customer_phone','SĐT khách'],['route_id','Tuyến có sẵn','routes'],['pickup','Điểm đón','text',true],['dropoff','Điểm trả','text',true],['departure_at','Ngày giờ khởi hành','datetime-local',true],['driver_id','Tài xế','drivers'],['vehicle_id','Xe','vehicles'],['fare','Cước chuyến','number'],['notes','Ghi chú']],periods:[['name','Tên kỳ','text',true],['from_date','Từ ngày','date'],['to_date','Đến ngày','date']],settlements:[['period_id','Kỳ đối soát','periods',true],['driver_id','Tài xế','drivers',true],['vehicle_id','Phương tiện','vehicles'],['gross_revenue','Tổng doanh số','number'],['promo','Khuyến mãi','number'],['card_rides','Doanh thu cuốc thẻ','number'],['card_fee','Phí thẻ','number'],['tips','Tiền tip','number'],['insured_trips','Chuyến bảo hiểm','number'],['insurance_fee','Phí bảo hiểm','number'],['app_fee','Phí ứng dụng','number'],['wallet','Số dư ví','number'],['wallet_return','Hoàn ví','number'],['collection_status','Truy thu','select',false,[['pending','Chưa thu'],['paid','Đã thu'],['none','Không truy thu']]],['note','Ghi chú']],ledger:[['driver_id','Tài xế','drivers',true],['settlement_id','Mã phiếu lương'],['entry_type','Loại chứng từ','select',true,[['receivable','Truy thu'],['payment','Đã thanh toán'],['adjustment','Điều chỉnh'],['refund','Hoàn tiền']]],['amount','Số tiền','number',true],['note','Nội dung']],users:[['email','Tên đăng nhập','text',true],['password','Mật khẩu (tối thiểu 12 ký tự)','password',true],['role','Vai trò','select',true,[['admin','Quản trị'],['accountant','Kế toán'],['director','Giám đốc'],['dispatcher','Điều phối'],['driver','Tài xế']]],['driver_id','Liên kết tài xế','drivers']]};
const COL={vehicles:[['plate','Biển số'],['type','Loại'],['brand','Hãng'],['model','Dòng xe'],['driver_name','Tài xế'],['status','Trạng thái']],drivers:[['full_name','Họ và tên'],['phone','SĐT'],['cccd','CCCD'],['license_no','GPLX'],['status','Trạng thái']],routes:[['name','Tên tuyến'],['pickup','Điểm đón'],['dropoff','Điểm đến'],['estimated_fare','Giá dự kiến']],bookings:[['code','Mã chuyến'],['customer_name','Khách'],['driver_name','Tài xế'],['plate','Biển số'],['departure_at','Xuất phát'],['fare','Cước'],['status','Trạng thái']],periods:[['name','Kỳ kế toán'],['from_date','Từ'],['to_date','Đến'],['status','Trạng thái']],settlements:[['full_name','Tài xế'],['period_name','Kỳ'],['plate','Biển số'],['gross_revenue','Doanh thu'],['app_fee','Phí app'],['wallet_return','Hoàn ví'],['collection_status','Truy thu']],ledger:[['full_name','Tài xế'],['entry_type','Loại'],['amount','Số tiền'],['note','Nội dung'],['created_at','Ngày tạo']],users:[['email','Tài khoản'],['role','Vai trò'],['driver_name','Tài xế'],['active','Hoạt động']],audit:[['actor','Thực hiện'],['action','Thao tác'],['entity','Đối tượng'],['entity_id','Mã bản ghi'],['created_at','Thời gian']]};
const titles=Object.fromEntries(NAV.map(([id,name])=>[id,name]));
const filtered=computed(()=>items.value.filter(x=>{
 if(search.value&&!JSON.stringify(x).toLowerCase().includes(search.value.toLowerCase()))return false;
 if(statusFilter.value&&String(x.status||x.collection_status||'')!==statusFilter.value)return false;
 if(typeFilter.value&&String(x.type||x.vehicle_type||'')!==typeFilter.value)return false;
 const date=String(x.departure_at||x.created_at||x.from_date||'').slice(0,10);
 if(dateFrom.value&&date&&date<dateFrom.value)return false;
 if(dateTo.value&&date&&date>dateTo.value)return false;
 return true;
}));
const statusOptions=computed(()=>[...new Set(items.value.map(x=>x.status||x.collection_status).filter(Boolean))]);
function downloadCurrent(){const cols=COL[page.value]||[];const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';const csv=[cols.map(x=>quote(x[1])).join(','),...filtered.value.map(x=>cols.map(c=>quote(x[c[0]])).join(','))].join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=page.value+'-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(url)}
const canEdit=computed(()=>user.value?.role==='admin'||(user.value?.role==='accountant'&&['periods','settlements','ledger'].includes(page.value))||(user.value?.role==='dispatcher'&&['vehicles','drivers','routes','bookings'].includes(page.value)));const canDelete=computed(()=>user.value?.role==='admin'||(user.value?.role==='accountant'&&page.value==='settlements'));
async function api(endpoint,method='GET',body){return httpApi(endpoint,method,body)}
const fail=e=>{error.value=e.message;setTimeout(()=>{error.value=''},6500)};const ok=msg=>{notice.value=msg;setTimeout(()=>notice.value='',3500)};
async function login(){loading.value=true;try{const r=await api('/login','POST',{email:loginName.value,password:password.value});token.value=r.token;sessionStorage.setItem('vantai_token',r.token);user.value=r.user;password.value='';await selectPage('dashboard')}catch(e){fail(e)}finally{loading.value=false}}
function logout(){token.value='';user.value=null;sessionStorage.removeItem('vantai_token');items.value=[];}
async function initialize(){if(!token.value)return;try{user.value=await api('/me');await selectPage('dashboard')}catch(e){fail(e)}}
async function loadRefs(){for(const [key,url] of Object.entries({drivers:'/drivers',vehicles:'/vehicles',routes:'/routes',periods:'/periods'})){try{refs.value[key]=await api(url)}catch{refs.value[key]=[]}}}
async function selectPage(id){page.value=id;sidebar.value=false;search.value='';statusFilter.value='';typeFilter.value='';dateFrom.value='';dateTo.value='';loading.value=true;try{if(id==='dashboard')dashboard.value=await api('/dashboard');else if(id!=='reports')items.value=await api('/'+id);await loadRefs()}catch(e){fail(e)}finally{loading.value=false}}
function newItem(row=null){editing.value=!!row;form.value=row?{...row}:{};if(!row){if(page.value==='vehicles')form.value={type:'motorbike',status:'available'};if(page.value==='users')form.value={role:'accountant'};if(page.value==='ledger')form.value={entry_type:'receivable'};if(page.value==='settlements')form.value={collection_status:'pending'};}modal.value=true;}
async function save(){try{if(!editing.value||['vehicles','drivers','routes','bookings','settlements'].includes(page.value)){const method=editing.value?'PUT':'POST';const url='/'+page.value+(method==='PUT'?'/'+form.value.id:'');await api(url,method,form.value)}else throw Error('Mục này không hỗ trợ sửa trực tiếp');modal.value=false;ok('Đã lưu thành công');await selectPage(page.value)}catch(e){fail(e)}}
async function remove(x){if(!window.confirm('Xóa bản ghi này? Một số dữ liệu được đánh dấu xóa để giữ lịch sử.'))return;try{await api('/'+page.value+'/'+x.id,'DELETE');ok('Đã xóa');await selectPage(page.value)}catch(e){fail(e)}}
async function changeStatus(x,status){try{await api('/bookings/'+x.id+'/status','PATCH',{status});ok('Cập nhật trạng thái thành công');await selectPage(page.value)}catch(e){fail(e)}}
async function lockPeriod(x){if(!window.confirm('Chốt kỳ này? Các phiếu đã chốt không thể sửa trực tiếp.'))return;try{await api('/periods/'+x.id+'/lock','PATCH');ok('Đã chốt kỳ');await selectPage(page.value)}catch(e){fail(e)}}
async function approvePeriod(x){if(!window.confirm('Duyệt kỳ đối soát này?'))return;try{await api('/periods/'+x.id+'/approve','PATCH');ok('Đã phê duyệt kỳ');await selectPage(page.value)}catch(e){fail(e)}}
async function reverse(x){if(!window.confirm('Hoàn chứng từ này?'))return;try{await api('/ledger/'+x.id+'/reverse','POST');ok('Đã hoàn chứng từ');await selectPage(page.value)}catch(e){fail(e)}}
async function toggleUser(x){try{await api('/users/'+x.id+'/active','PATCH',{active:!x.active});ok('Đã cập nhật tài khoản');await selectPage(page.value)}catch(e){fail(e)}}
const format=(x,k)=>{if(x===null||x===undefined||x==='')return '—';if(k==='type')return x==='car'?'Ô tô':'Xe máy';if(['fare','estimated_fare','gross_revenue','app_fee','wallet_return','amount'].includes(k))return Number(x).toLocaleString('vi-VN')+' ₫';if(k==='active')return x?'Hoạt động':'Đã khóa';if(k==='created_at'||k==='departure_at')return String(x).replace('T',' ').slice(0,16);return x};
function optionLabel(kind,r){return kind==='drivers'?r.full_name+' · '+r.phone:kind==='vehicles'?r.plate:kind==='periods'?r.name:r.name};
const colors={pending:'amber',accepted:'blue',completed:'green',paid:'green',locked:'purple',approved:'green',active:'green',available:'green',rejected:'red',cancelled:'red',inactive:'red',draft:'blue'};
window.addEventListener('auth-expired',logout);onMounted(initialize);
</script>
<template>
<div v-if="!user" class="auth-layout"><div class="login-art"><div class="brand-mark">V</div><h1>Vận hành thông minh,<br/>dữ liệu tập trung.</h1><p>Điều phối chuyến xe, quản lý tài xế, đối soát và công nợ trong cùng một hệ thống.</p></div><form class="login-card" @submit.prevent="login"><div class="eyebrow">HỆ THỐNG QUẢN LÝ VẬN TẢI</div><h2>Đăng nhập quản trị</h2><p>Nhập tài khoản đã được cấp để tiếp tục.</p><label>Tài khoản<input v-model="loginName" autocomplete="username" required placeholder="Tên đăng nhập"/></label><label>Mật khẩu<input v-model="password" type="password" autocomplete="current-password" required placeholder="Nhập mật khẩu"/></label><button class="primary full" :disabled="loading">{{loading?'Đang xác thực...':'Đăng nhập'}}</button><div v-if="error" class="alert">{{error}}</div></form></div>
<div v-else class="shell"><aside class="sidebar" :class="{open:sidebar}"><div class="sidebar-brand"><div class="brand-mark small">V</div><span>VẬN TẢI <b>PRO</b></span></div><button v-for="[id,name,Icon] in NAV" :key="id" v-show="user.role==='admin'|| (user.role==='accountant'&&['dashboard','periods','settlements','ledger','reports'].includes(id)) || (user.role==='director'&&['dashboard','reports','periods'].includes(id)) || (user.role==='dispatcher'&&['dashboard','vehicles','drivers','routes','bookings'].includes(id)) || (user.role==='driver'&&['dashboard','bookings','settlements'].includes(id))" class="nav-item" :class="{active:page===id}" @click="selectPage(id)"><component :is="Icon" :size="18"/><span>{{name}}</span></button><div class="nav-bottom"><button class="nav-item" @click="logout"><LogOut :size="18"/>Đăng xuất</button></div></aside><main class="content"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile" @click="sidebar=!sidebar"><Menu :size="22"/></button><div class="crumb">Quản trị <span>/</span> {{titles[page]}}</div></div><div class="identity"><div><b>{{user.email}}</b><small>{{({admin:'Quản trị viên',accountant:'Kế toán',director:'Giám đốc',dispatcher:'Điều phối',driver:'Tài xế'})[user.role]||user.role}}</small></div><div class="avatar">{{user.email.slice(0,1).toUpperCase()}}</div></div></header><section class="workspace"><div class="page-title"><div><h1>{{titles[page]}}</h1></div><div class="head-actions"><button v-if="page!=='dashboard'&&page!=='audit'&&page!=='reports'&&canEdit" class="primary" @click="newItem()"><Plus :size="16"/> Thêm mới</button></div></div>
<div v-if="error" class="alert"><AlertCircle :size="16"/>{{error}}</div><div v-if="notice" class="success"><CheckCircle2 :size="16"/>{{notice}}</div>
<ReportsView v-if="page==='reports'" :role="user.role"/><DashboardView v-else-if="page==='dashboard'" @navigate="selectPage"/><template v-else><div class="panel table-panel"><div class="table-head"><div><h3>Danh sách {{titles[page].toLowerCase()}}</h3><span>{{filtered.length}} bản ghi</span></div><div class="list-tools"><button class="secondary" @click="downloadCurrent"><Download :size="14"/> Excel</button><div class="search"><Search :size="17"/><input v-model="search" placeholder="Tìm kiếm..."/></div></div></div><div class="list-filters" v-if="['vehicles','drivers','bookings','periods','settlements'].includes(page)"><label>Trạng thái<select v-model="statusFilter"><option value="">Tất cả trạng thái</option><option v-for="x in statusOptions" :key="x" :value="x">{{x}}</option></select></label><label v-if="page==='vehicles'">Loại xe<select v-model="typeFilter"><option value="">Tất cả xe</option><option value="car">Ô tô</option><option value="motorbike">Xe máy</option></select></label><template v-if="['bookings','settlements'].includes(page)"><label>Từ ngày<input type="date" v-model="dateFrom"/></label><label>Đến ngày<input type="date" v-model="dateTo"/></label></template><button class="secondary" @click="search='';statusFilter='';typeFilter='';dateFrom='';dateTo=''">Xóa lọc</button></div><DataTable :rows="filtered" :columns="COL[page]" :formatter="format" :page-size="12"><template v-if="canEdit||canDelete||user.role==='director'&&page==='periods'" #actions="{row:r}"><div class="actions"><button v-if="canEdit&&['vehicles','drivers','routes','bookings','settlements','periods'].includes(page)" class="action" title="Sửa" @click="newItem(r)"><Edit3 :size="15"/></button><button v-if="canDelete&&['vehicles','drivers','routes','bookings','settlements'].includes(page)" class="action danger" title="Xóa" @click="remove(r)"><Trash2 :size="15"/></button><template v-if="page==='bookings'&&r.status==='pending'"><button class="mini green" @click="changeStatus(r,'accepted')">Nhận</button><button class="mini red" @click="changeStatus(r,'rejected')">Từ chối</button></template><button v-if="page==='bookings'&&r.status==='accepted'" class="mini" @click="changeStatus(r,'completed')">Hoàn tất</button><button v-if="page==='periods'&&r.status==='locked'&&user.role==='director'" class="mini green" @click="approvePeriod(r)">Duyệt kỳ</button><button v-if="page==='periods'&&r.status==='draft'&&canEdit" class="mini" @click="lockPeriod(r)">Chốt kỳ</button><button v-if="page==='ledger'&&!r.reversed_at" class="mini red" @click="reverse(r)">Hoàn</button><button v-if="page==='users'&&r.id!==user.id" class="mini" @click="toggleUser(r)">{{r.active?'Khóa':'Mở khóa'}}</button></div></template></DataTable></div></template>
</section></main></div>
<div v-if="modal" class="modal-shade" @click.self="modal=false"><div class="modal"><div class="modal-head"><div><h2>{{editing?'Cập nhật':'Thêm mới'}} · {{titles[page]}}</h2></div><button class="icon-button" @click="modal=false"><X :size="21"/></button></div><form @submit.prevent="save"><div class="form-grid"><label v-for="field in F[page]||[]" :key="field[0]">{{field[1]}}<span v-if="field[3]"> *</span><select v-if="field[2]==='select'" v-model="form[field[0]]" :required="!!field[3]"><option value="">— Chọn —</option><option v-for="[v,t] in field[4]||[]" :key="v" :value="v">{{t}}</option></select><select v-else-if="['drivers','vehicles','routes','periods'].includes(field[2])" v-model="form[field[0]]" :required="!!field[3]"><option value="">— Chọn —</option><option v-for="r in refs[field[2]]" :key="r.id" :value="r.id">{{optionLabel(field[2],r)}}</option></select><input v-else v-model="form[field[0]]" :type="field[2]||'text'" :required="!!field[3]" :min="field[2]==='number'?0:undefined" :step="field[2]==='number'?'any':undefined"/></label></div><div class="modal-foot"><button type="button" class="secondary" @click="modal=false">Hủy</button><button class="primary" type="submit"><CheckCircle2 :size="17"/> Lưu dữ liệu</button></div></form></div></div>
</template>
